UPDATE rental_order SET deposit_status=CASE WHEN deposit_paid_amount_fen=0 THEN 'settled'
    WHEN deposit_paid_amount_fen=deposit_refunded_amount_fen THEN 'refunded'
    WHEN deposit_deducted_amount_fen+deposit_refunded_amount_fen=deposit_paid_amount_fen THEN 'settled' ELSE 'refunding' END,updated_at=#{at},version=version+1 WHERE id=#{orderId}
